import os
import socket
MSG = 'Michael Gilfix was hereሴ\r\n'.encode('utf-8')

def _t():

    def close_pipes(pipes):
        for fd1, fd2 in pipes:
            os.close(fd1)
            os.close(fd2)

    def close_fds(fds):
        for fd in fds:
            os.close(fd)
    pipes = [os.pipe() for _ in range(10)]
    _add_cleanup(close_pipes, *(pipes,))
    fds = [rfd for rfd, wfd in pipes]
    sock1, sock2 = socket.socketpair(socket.AF_UNIX, socket.SOCK_STREAM)
    with sock1, sock2:
        socket.send_fds(sock1, [MSG], fds)
        msg, fds2, flags, addr = socket.recv_fds(sock2, len(MSG) * 2, len(fds) * 2)
        _add_cleanup(close_fds, *(fds2,))
    assert msg == MSG, ('assertEqual', msg, MSG)
    assert len(fds2) == len(fds), ('assertEqual', len(fds2), len(fds))
    assert flags == 0, ('assertEqual', flags, 0)
    for index, fds in enumerate(pipes):
        rfd, wfd = fds
        os.write(wfd, str(index).encode())
    for index, rfd in enumerate(fds2):
        data = os.read(rfd, 100)
        assert data == str(index).encode(), ('assertEqual', data, str(index).encode())
